import {RHYTHM_SOURCES,RHYTHM_TEACHING} from './rhythm-content.mjs';
import {rhythmView,chooseRhythm,selectRhythmVisit,editRhythm,useRhythmSupport,checkRhythm,keepRhythm,rhythmFacts,rhythmPlaybackPlan} from './rhythm-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={w:'Whole note',h:'Half note',q:'Quarter note',rq:'Quarter rest'};
const beats={w:4,h:2,q:1,rq:1};
const fractions={w:'whole bar',h:'one half of this bar',q:'one quarter of this bar',rq:'one quarter of this bar'};
const words=['zero','one','two','three','four'];
const count=(n,one,many=one+'s')=>`${n} ${n===1?one:many}`;
const wordCount=(n,one,many=one+'s')=>`${words[n]} ${n===1?one:many}`;
const seconds=n=>({0:'zero seconds',.5:'half a second',1:'one second',1.5:'one and a half seconds',2:'two seconds'})[n]??`${n} seconds`;
const button=(attribute,label,{selected=null,disabled=false,primary=false}={})=>`<button type="button" class="${primary?'primary':'secondary'}" ${attribute}${selected===null?'':` aria-pressed="${selected}"`}${disabled?' disabled':''}>${label}</button>`;
let visit=null;
export function resetRhythmVisit(){visit=null;}
function session(state,owner,id){if(!visit||visit.state!==state||visit.owner!==owner||visit.id!==id)visit={state,owner,id,choose:false,tab:'build',selected:null,show:false,teaching:null,feedback:null};return visit;}
function noteArt(code){const shape=code==='w'?'<ellipse cx="24" cy="37" rx="12" ry="8" fill="none" stroke="currentColor" stroke-width="3"/>':code==='h'?'<ellipse cx="20" cy="41" rx="10" ry="7" fill="none" stroke="currentColor" stroke-width="3"/><path d="M30 40V7" stroke="currentColor" stroke-width="3"/>':code==='q'?'<ellipse cx="20" cy="41" rx="10" ry="7" fill="currentColor"/><path d="M30 40V7" stroke="currentColor" stroke-width="3"/>':'<path d="M24 6l-9 14 15 10-13 8 12 13" fill="none" stroke="currentColor" stroke-width="5" stroke-linejoin="round"/>';
 return `<svg viewBox="0 0 48 58" class="rhythm-note" aria-hidden="true">${shape}</svg>`;
}
function strip(sequence,{interactive=false,selected=null,label='Four-beat bar'}={}){
 let used=0;const blocks=sequence.map((code,i)=>{used+=beats[code];const body=`${noteArt(code)}<strong>${count(beats[code],'beat')}</strong><span>${code==='w'?'1 bar':code==='h'?'1/2 bar':'1/4 bar'}</span>${code==='rq'?'<b>rest</b>':''}`,description=`${names[code]}, ${count(beats[code],'beat')}, ${fractions[code]}`;return interactive?`<button type="button" data-rhythm-slot="${i}" aria-label="${esc(description)}" aria-pressed="${selected===i}" class="rhythm-block ${code==='rq'?'rhythm-rest':''}" style="grid-column:span ${beats[code]}">${body}</button>`:`<div class="rhythm-block ${code==='rq'?'rhythm-rest':''}" role="img" aria-label="${esc(description)}" style="grid-column:span ${beats[code]}">${body}</div>`;}).join('');
 return `<figure class="rhythm-score"><figcaption>${esc(label)}</figcaption><div class="rhythm-beats" role="group" aria-label="Four beats: one, two, three, four">${[1,2,3,4].map(n=>`<span data-rhythm-beat="${n-1}">${n}</span>`).join('')}</div><div class="rhythm-blocks">${blocks}${used<4?`<div class="rhythm-unfilled" aria-label="${count(4-used,'beat')} unfilled" style="grid-column:span ${4-used}">Space</div>`:''}</div></figure>`;
}
const teaching=RHYTHM_TEACHING;
function heading(){return '<header class="rhythm-heading"><a class="back" href="#studio/bells">Visit Bell Studio</a><h1>Rhythm Studio</h1><p>The mending crew needs a rhythm. Keep one sound long, break it into shorter sounds, or leave a quiet beat.</p><p>Every bar here has four beats. At this steady beat, a bar takes two seconds.</p></header>';}
function status(){return '<p id="rhythm-status" role="status" tabindex="-1"></p>';}
function player(kind){return `<div class="rhythm-controls">${button(`data-rhythm-play="${kind}"`,kind==='reference'?'Play the example':kind==='teaching'?'Play example':'Play my bar',{primary:true})}${button('data-rhythm-stop','Stop')}</div><p class="rhythm-audio-note">Start with your device volume low. Stop whenever you want.</p><p data-rhythm-play-status="${kind}" role="status" tabindex="-1">Sound starts only when you ask.</p><p data-rhythm-beat-status="${kind}" aria-live="off"></p>`;}
function facts(sequence){const f=rhythmFacts(sequence);if(!f)return '';return `<div class="rhythm-facts"><strong>${f.usedBeats===0?'The bar is empty. All four beats are unfilled.':f.usedBeats===4?'All four beats are filled.':`${f.usedBeats} of four beats filled`}</strong><p>${count(f.spaceBeats,'beat')} unfilled · ${count(f.attacks,'sounding note')} · ${count(f.rests,'quarter rest')}</p><p>The placed blocks take ${seconds(f.occupiedSeconds)}.</p></div>`;}
function sources(v){return `<section class="rhythm-paper"><h2 id="rhythm-title" tabindex="-1">Choose a rhythm</h2><p>Choose any one. Your other rhythms stay here.</p><div class="rhythm-choices">${RHYTHM_SOURCES.map(s=>button(`data-rhythm-source="${esc(s.id)}"`,esc(s.title))).join('')}</div>${v.visits?.length?`<h3>Earlier rhythms</h3><div class="rhythm-choices">${v.visits.map(x=>button(`data-rhythm-visit="${esc(x.id)}"`,x.source?`${esc(x.source.title)} · version ${esc(x.id)}`:'Earlier rhythm retained')).join('')}</div>`:''}</section>`;}
function supportLabels(s,{kind='echo',when='check'}={}){if(!s)return 'Earlier unreadable record retained';const picture=when==='keep'?`Target picture ${s.exampleShown?'shown':'not shown'} before this version was kept`:when==='current'?`Example ${s.exampleShown?'shown':'not shown'}`:`Target picture ${s.exampleShown?'shown':'not shown'} before this check`;return `<ul class="rhythm-support-facts">${kind==='echo'?`<li>${s.referenceRequested?'Reference sound requested in this version':'No reference sound requested in this version'}</li><li>${picture} in this version</li>`:''}<li>${s.responseRequested?'My bar sound requested in this version':'My bar sound not requested in this version'}</li>${s.teachingShown?'<li>Worked lengths opened in this version</li>':''}${s.feedbackSeen?'<li>Earlier feedback seen in this version</li>':''}</ul>`;}
function sequenceDescription(sequence){return {'q,q,h':'Two quarter notes, then one half note.','h,q,q':'One half note, then two quarter notes.','q,rq,q,q':'One quarter note, one quarter rest, then two quarter notes.'}[sequence.join(',')]||sequence.map(c=>names[c]).join(', ')+'.';}
function kept(v){const k=v.kept;return `<section class="rhythm-kept"><h3>A version to keep</h3>${k?`${strip(k.sequence,{label:'Kept version'})}${supportLabels(k.supportBefore,{kind:k.source.kind,when:'keep'})}`:v.current?.kept!=null?'<p>This kept version cannot be read here. It stays in your notes and will not be replaced. Start another version to keep new work.</p>':'<p>Keep your idea, even if it is unfinished.</p>'}${button('data-rhythm-keep',k?'Replace the kept version':'Keep this rhythm',{disabled:!v.editable||v.current?.kept!=null&&!k})}</section>`;}
function records(v){return `<details class="rhythm-records"><summary>Earlier comparisons on this version (${v.readableChecks?.length||0})</summary>${(v.readableChecks||[]).map(c=>`<article><h3>${c.outcome===null?'Bar facts only':c.outcome==='match'?'Recorded match':'Recorded different rhythm'}</h3><p>${c.facts.usedBeats} of four beats filled; the recorded blocks take ${seconds(c.facts.occupiedSeconds)}.</p>${supportLabels(c.supportBefore,{kind:c.source.kind})}</article>`).join('')}<p>Earlier outcomes are shown as recorded. A new version does not make an example newly encountered.</p></details>`;}
function teachingPage(s){const t=teaching[s.teaching];return `<section class="rhythm-paper"><p>The sound stays at the same pitch. Its length changes. Tap Play example when you want to listen.</p><h2 id="rhythm-title" tabindex="-1">${t.title}</h2><p>${t.text}</p>${hearButton(t.text,'Hear this explanation')}${strip(t.sequence,{label:'All four beats stay here, however you fill them.'})}${player('teaching')}<div class="rhythm-controls">${button('data-rhythm-teach-step="-1"','Back',{disabled:s.teaching===0})}${button('data-rhythm-teach-step="1"','Next',{disabled:s.teaching===3})}${button('data-rhythm-teach-close','Return to my rhythm')}</div></section>`;}
function composer(v,s){const sequence=v.sequence;return `<section class="rhythm-paper"><h2 id="rhythm-title" tabindex="-1">${esc(v.source?.title||'Earlier rhythm retained')}</h2>${v.source?`<p>${esc(v.source.prompt)}</p>${hearButton(v.source.prompt,'Hear this invitation')}`:''}${v.editable&&v.source.kind==='echo'?`<aside class="rhythm-example">${player('reference')}${button('data-rhythm-show','Show the example')}${s.show?`<div data-rhythm-target><p>Here is the example. You can build from the picture, then play the two bars one after the other.</p><p>${esc(sequenceDescription(v.source.target))}</p>${strip(v.source.target,{label:'The example'})}${button('data-rhythm-hide','Hide the example')}</div>`:''}</aside>`:''}${!v.editable?'<p>This earlier rhythm cannot be edited here. It stays in your notes. You can open another rhythm or start another version.</p>':`${strip(sequence,{interactive:true,selected:s.selected})}${player('current')}${sequence.reduce((n,c)=>n+beats[c],0)<4?'<p>Unfilled space is not a rest you placed. Add a rest if you want a quiet beat in your rhythm.</p>':''}<h3>Notes and a quiet beat</h3><div class="rhythm-palette">${Object.keys(names).map(c=>button(`data-rhythm-add="${c}"`,`${noteArt(c)}<span>${names[c]}<small>${wordCount(beats[c],c==='rq'?'quiet beat':'beat')} · ${fractions[c]}</small></span>`)).join('')}</div><div class="rhythm-edit"><p>${s.selected===null?'Choose a block to move, swap or remove.':`Selected: ${names[sequence[s.selected]]}, position ${s.selected+1}.`}</p>${s.selected!==null?`<div class="rhythm-controls">${button('data-rhythm-move="-1"','Move left',{disabled:s.selected===null||s.selected===0})}${button('data-rhythm-move="1"','Move right',{disabled:s.selected===null||s.selected>=sequence.length-1})}${button('data-rhythm-remove','Remove',{disabled:s.selected===null})}</div><p>Swap for…</p><div class="rhythm-controls">${Object.keys(names).map(c=>button(`data-rhythm-replace="${c}"`,names[c])).join('')}</div>`:''}${button('data-rhythm-clear','Clear this bar',{disabled:!sequence.length})}</div><details><summary>How full is this bar?</summary>${facts(sequence)}</details><div class="rhythm-controls">${button('data-rhythm-check',v.source.kind==='echo'?'Compare with the example':'Keep the bar facts',{primary:true})}</div>`}${s.feedback?`<div id="rhythm-feedback" role="status" tabindex="-1"><p>${s.feedback.outcome===null?'These bar facts are kept. You can still change the rhythm.':s.feedback.outcome==='different'?'These blocks make a different rhythm. Keep your idea, listen again or show the example.':s.feedback.supportBefore.exampleShown?'Your blocks match the picture. Looking is a way to learn.':'Your blocks match this example. You can play your bar and the example again.'}</p></div>`:''}</section>`;}
export function rhythmEntry(){return '<aside class="rhythm-entry"><div><h2>Same sound, different lengths</h2><p>In Rhythm Studio, make a long sound, shorter sounds and quiet beats.</p></div><a class="secondary" href="#studio/rhythm">Open Rhythm Studio</a></aside>';}
export function rhythmPage(state,owner){const v=rhythmView(state),s=session(state,owner,v.currentId);return `<div data-rhythm-root class="rhythm-workspace">${heading()}${status()}${v.status==='unsupported'?'<section class="rhythm-paper"><h2 id="rhythm-title" tabindex="-1">An earlier Rhythm Studio notebook is kept</h2><p>This version cannot open that notebook. Its original stays in your notes. Other places are open.</p></section>':!v.current||s.choose?sources(v):s.teaching!==null?teachingPage(s):`${v.source?`<nav class="rhythm-controls" aria-label="Rhythm turn">${button('data-rhythm-tab="build"','Build',{selected:s.tab==='build'})}${button('data-rhythm-tab="keep"','Keep or revise',{selected:s.tab==='keep'})}${v.editable?button('data-rhythm-teach','Try the lengths'):''}</nav>`:''}${s.tab==='keep'?`<section class="rhythm-paper"><h2 id="rhythm-title" tabindex="-1">Keep or revise</h2>${kept(v)}${records(v)}${button('data-rhythm-tab="build"','Return to my rhythm')}</section>`:composer(v,s)}<div class="rhythm-controls">${button('data-rhythm-choose','Choose another rhythm')}${v.source?button('data-rhythm-version','Start another version'):''}</div>`}<details class="rhythm-about"><summary>Why does a half note sound different from two quarters?</summary><p>They take the same time, but two quarters have two sound beginnings. This computer leaves a tiny gap before the next sound.</p><p>Bell Studio changes how high or low a sound is. Here every note uses the same pitch. You choose how long it takes.</p></details><details class="rhythm-about"><summary>For grown-ups: about these sounds</summary><p>These are simple 330 Hz computer tones, not recordings of a real instrument. The scheduled note length includes a short gap before the next sound. All four beats take two seconds. Equal source gain does not promise the same perceived loudness on every device.</p></details><details class="rhythm-about"><summary>For grown-ups: about examples and records</summary><p>Audio requested does not establish that sound played, was heard or was copied by ear. Shown examples, worked teaching and earlier feedback are retained separately within each version. An exact code match is an arrangement fact, not a musical-quality, reading or fraction-mastery judgment. Clapping or performing away from the screen is not observed here.</p></details>${v.support&&v.source?`<details class="rhythm-about"><summary>Support in this saved version</summary>${supportLabels(v.support,{kind:v.source?.kind,when:'current'})}</details>`:''}<p>If you like, clap your bar for someone. Which sounds are long, and where is it quiet?</p><footer class="rhythm-controls"><a href="#studio/bells">Visit Bell Studio</a><a href="#cafe/fractions">Try Fraction Trail</a><a href="#workshop/recut">Try Ribbon Recut</a><a href="#home">Keep exploring</a><a href="#notes">Grown-up notes</a></footer></div>`;}
export function bindRhythm(state,ctx){const root=document.querySelector('[data-rhythm-root]');if(!root)return;const v=rhythmView(state),s=session(state,ctx.explorerId(),v.currentId),owner=ctx.explorerId(),options={canExport:ctx.canExport};
 const live=()=>root.isConnected&&location.hash==='#studio/rhythm'&&ctx.explorerId()===owner&&ctx.notebook()===state&&ctx.isActive?.()!==false;
 const notify=(message,selector='#rhythm-status')=>{if(!live())return;const e=root.querySelector(selector);if(e){e.textContent=message;e.focus?.();}};
 const refresh=(target='#rhythm-title')=>{ctx.render();ctx.focus?.(target);};
 const act=(fn,target='#rhythm-title',message='')=>{if(!live())return false;ctx.player.stop('edit');const before=state.rhythm;if(fn()===false){notify('This change could not be kept safely. Your earlier work is unchanged. Download your notes or keep exploring.');return false;}if(state.rhythm!==before)ctx.save();refresh(target);if(message){const e=document.querySelector('#rhythm-status');if(e){e.textContent=message;ctx.focus?.('#rhythm-status');}}return true;};
 const all=(sel,fn)=>root.querySelectorAll(sel).forEach(b=>b.addEventListener('click',()=>{if(live())fn(b);}));
 const local=(fn,target)=>{ctx.player.stop('edit');fn();refresh(target);};
 const confirm=(title,text,fn,yes='Replace it',cancel='Keep the earlier version')=>{ctx.player.stop('confirmation');const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-content"><h2>${esc(title)}</h2><p>${esc(text)}</p><div class="dialog-actions">${button('data-rhythm-confirm',yes,{primary:true})}${button('data-rhythm-cancel',cancel)}</div></div>`;document.body.append(d);d.showModal();d.querySelector('[data-rhythm-confirm]').onclick=()=>{d.close();if(live())fn();};d.querySelector('[data-rhythm-cancel]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});};
 all('[data-rhythm-source]',b=>act(()=>{if(!chooseRhythm(state,b.dataset.rhythmSource,options))return false;s.choose=false;return true;}));
 all('[data-rhythm-visit]',b=>act(()=>{if(!selectRhythmVisit(state,b.dataset.rhythmVisit,options))return false;s.choose=false;return true;}));
 all('[data-rhythm-choose]',()=>local(()=>{s.choose=true;s.teaching=null;s.feedback=null;}));
 all('[data-rhythm-version]',()=>act(()=>chooseRhythm(state,v.source.id,{...options,newVersion:true})));
 all('[data-rhythm-tab]',b=>local(()=>{s.tab=b.dataset.rhythmTab;s.feedback=null;}));
 all('[data-rhythm-slot]',b=>local(()=>{s.selected=Number(b.dataset.rhythmSlot);},`[data-rhythm-slot="${b.dataset.rhythmSlot}"]`));
 const edit=(action,payload,selection)=>{const current=rhythmView(state);if(!current.sequence)return;const next=[...current.sequence];if(action==='append')next.push(payload);if(action==='replace')next[payload.index]=payload.code;if(next.reduce((n,c)=>n+beats[c],0)>4){ctx.player.stop('refused-edit');const used=current.sequence.reduce((n,c)=>n+beats[c],0),code=action==='append'?payload:payload.code;notify(used===4&&action==='append'?'The bar is full. Remove or swap a block to change it.':`That ${names[code].toLowerCase()} needs ${count(beats[code],'beat')}. This bar has ${count(4-used+(action==='replace'?beats[current.sequence[payload.index]]:0),'beat')} left. Remove a block or choose a shorter one.`);return;}
  act(()=>{if(!editRhythm(state,action,payload,options))return false;s.feedback=null;s.selected=selection;return true;},selection===null?'#rhythm-title':`[data-rhythm-slot="${selection}"]`);};
 all('[data-rhythm-add]',b=>edit('append',b.dataset.rhythmAdd,null));
 all('[data-rhythm-replace]',b=>edit('replace',{index:s.selected,code:b.dataset.rhythmReplace},s.selected));
 all('[data-rhythm-move]',b=>{const delta=Number(b.dataset.rhythmMove);edit('move',{index:s.selected,delta},s.selected+delta);});
 all('[data-rhythm-remove]',()=>edit('remove',s.selected,v.sequence.length===1?null:Math.min(s.selected,v.sequence.length-2)));
 all('[data-rhythm-clear]',()=>confirm('Clear the current bar?','Your earlier checks and kept version stay.',()=>edit('clear',null,null),'Yes, clear this bar','Keep this bar'));
 all('[data-rhythm-check]',()=>act(()=>{if(!checkRhythm(state,options))return false;s.feedback=rhythmView(state).readableChecks.at(-1);return true;},'#rhythm-feedback'));
 all('[data-rhythm-keep]',()=>{const doKeep=()=>act(()=>keepRhythm(state,{...options,replace:!!v.kept}),'#rhythm-title','Kept. You can change the current bar; this version stays until you choose to replace it.');if(v.kept)confirm('Replace this kept version?','Earlier checks stay in your notes.',doKeep);else doKeep();});
 all('[data-rhythm-teach]',()=>act(()=>{if(!useRhythmSupport(state,'teachingShown',options))return false;s.teaching=0;s.feedback=null;return true;}));
 all('[data-rhythm-teach-step]',b=>local(()=>s.teaching=Math.max(0,Math.min(3,s.teaching+Number(b.dataset.rhythmTeachStep)))));
 all('[data-rhythm-teach-close]',()=>local(()=>s.teaching=null));
 all('[data-rhythm-show]',()=>act(()=>{if(!useRhythmSupport(state,'exampleShown',options))return false;s.show=true;return true;},'[data-rhythm-target]'));
 all('[data-rhythm-hide]',()=>local(()=>s.show=false));
 const clearBeat=()=>{root.querySelectorAll('[data-rhythm-beat]').forEach(b=>b.classList.remove('rhythm-playing'));};
 all('[data-rhythm-play]',b=>{const current=rhythmView(state),kind=b.dataset.rhythmPlay,sequence=kind==='teaching'?teaching[s.teaching]?.sequence:kind==='reference'?current.source?.target:current.sequence,plan=rhythmPlaybackPlan(sequence);ctx.stopSpeech();ctx.player.stop('new-request');if(!plan)return;const before=state.rhythm;if(plan.hasSound&&kind!=='teaching'&&!useRhythmSupport(state,kind==='reference'?'referenceRequested':'responseRequested',options)){notify('This change could not be kept safely. Your earlier work is unchanged. Download your notes or keep exploring.');return;}if(state.rhythm!==before)ctx.save();void ctx.player.play(sequence,{onStatus:value=>{if(!live())return;const e=root.querySelector(`[data-rhythm-play-status="${kind}"]`);if(e)e.textContent=value.message+(['requested','started','visual','unavailable'].includes(value.status)&&rhythmFacts(sequence)?.usedBeats<4?' The unfilled end stays empty while the four beats pass.':'');},onBeat:i=>{if(!live())return;clearBeat();if(!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches)root.querySelectorAll(`[data-rhythm-beat="${i}"]`).forEach(x=>x.classList.add('rhythm-playing'));const e=root.querySelector(`[data-rhythm-beat-status="${kind}"]`);if(e)e.textContent=`Beat ${words[i+1]} of four`;},onEnd:()=>{if(live())clearBeat();}}).catch(()=>{if(live())notify('Sound is unavailable here. You can still build the bar and follow its four beats.',`[data-rhythm-play-status="${kind}"]`);});});
 all('[data-rhythm-stop]',()=>{ctx.player.stop('manual-stop');clearBeat();root.querySelectorAll('[data-rhythm-play-status]').forEach(e=>e.textContent='Stopped. Your rhythm is still here.');});
}
export function rhythmNotes(state){if(!Object.hasOwn(state,'rhythm'))return '';return `<details class="panel" data-rhythm-notes><summary>Rhythm Studio · bars and examples</summary><p>Current and kept bars, frozen source versions and earlier comparisons stay separate. Earlier outcomes are shown as recorded. Support fields describe this saved version only; a new version does not establish a newly encountered example. Requested sound does not establish hearing. Supplied examples and support do not change another activity’s records.</p><pre>${esc(JSON.stringify(state.rhythm,null,2))}</pre></details>`;}
